      put(d, 'sup/migrations/0001_init.sql', 'x');
    }));
    return julgar(dados).falhas.some((f) => f.tipo === 'sem-reserva' && /0001_init/.test(f.arquivo));
  })());
  check('RN-C2: item PASTA sem extensão (Prisma) sem reserva → FALHA', (() => {
