73	export function selfTest() {
74	  const casos = [];
75	  const check = (nome, cond) => casos.push({ nome, ok: Boolean(cond) });
76	
77	  // ── auditarLeis: o que NUNCA pode passar (núcleo estrutural, inalterado) ──
78	  check('BYPASS: 11 leis (falta LEI DA PROVA) → contagem → reprova',
79	    auditarLeis(construirSecao(NOMES_CANONICOS.filter((_, idx) => idx !== 6))).ok === false);
80	  check('contagem: mensagem nomeada "contagem"',
81	    auditarLeis(construirSecao(NOMES_CANONICOS.filter((_, idx) => idx !== 6)))
82	      .problemas.some((p) => p.startsWith('contagem')));
83	
84	  check('BYPASS: lei renomeada (nome fora do canônico) → nome → reprova',
85	    auditarLeis(construirSecao(NOMES_CANONICOS.map((n, idx) => (idx === 0 ? 'LEI DO PAPEL TROCADA' : n)))).ok === false);
86	  check('nome: mensagem nomeada "nome" com esperado/achou', (() => {
87	    const problemas = auditarLeis(construirSecao(NOMES_CANONICOS.map((n, idx) => (idx === 0 ? 'LEI DO PAPEL TROCADA' : n)))).problemas;
88	    return problemas.some((p) => p.startsWith('nome') && p.includes('esperado') && p.includes('achou'));
89	  })());
90	
91	  check('BYPASS: duas leis trocadas de ordem (conteúdo trocado, números 1..12 intactos) → reprova', (() => {
92	    const trocadas = [...NOMES_CANONICOS];
93	    [trocadas[2], trocadas[3]] = [trocadas[3], trocadas[2]];
94	    return auditarLeis(construirSecao(trocadas)).ok === false;
95	  })());
96	
97	  check('BYPASS: número pulado (4 vira 5, resto sobe 1) → numeracao → reprova', (() => {
98	    const numeros = [1, 2, 3, 5, 6, 7, 8, 9, 10, 11, 12, 13];
99	    return auditarLeis(construirSecao(NOMES_CANONICOS, { numeros })).ok === false;
100	  })());
101	  check('numeracao: mensagem nomeada "numeracao" com posição/número', (() => {
102	    const numeros = [1, 2, 3, 5, 6, 7, 8, 9, 10, 11, 12, 13];
103	    return auditarLeis(construirSecao(NOMES_CANONICOS, { numeros }))
104	      .problemas.some((p) => p.startsWith('numeracao') && p.includes('posição'));
105	  })());
106	
107	  check('BYPASS: seção ausente → secao-ausente → reprova',
108	    auditarLeis('# projeto qualquer\nsem a seção das leis em lugar nenhum aqui.\n').ok === false);
109	  check('secao-ausente: mensagem nomeada corretamente',
110	    auditarLeis('# nada\n').problemas[0].startsWith('secao-ausente'));
111	
112	  check('BYPASS: seção duplicada (aparece 2x) → secao-duplicada → reprova',
113	    auditarLeis(`${construirSecao()}\n${construirSecao()}`).ok === false);
114	  check(
115	    'LI-6 (R3): secao-duplicada — mensagem nomeada corretamente via .some(p => p?.startsWith(...)), ' +
116	    'não problemas[0] direto (mata mutante M4 com ✗ limpo, sem CRASHAR)',
117	    auditarLeis(`${construirSecao()}\n${construirSecao()}`).problemas.some((p) => p?.startsWith('secao-duplicada')));
118	
119	  check('BYPASS (TRUNCADO): seção cortada no meio (só 6 leis presentes) → contagem → reprova',
120	    auditarLeis(construirSecao().split('\n').slice(0, 8).join('\n')).ok === false);
121	
122	  check('BYPASS (INVISÍVEL): U+200B dentro do nome não é absorvido pelo colapso de espaço → nome → reprova', (() => {
123	    const zwsp = String.fromCharCode(0x200b); // zero-width space: NÃO casa \s no JS
124	    const nomeComInvisivel = `LEI DO PA${zwsp}PEL`;
125	    return auditarLeis(construirSecao(NOMES_CANONICOS.map((n, idx) => (idx === 0 ? nomeComInvisivel : n)))).ok === false;
126	  })());
127	
128	  check('BYPASS (NULO): auditarLeis(null/undefined/"") nunca é "ok" — vira secao-ausente, não aprovação silenciosa',
129	    auditarLeis(null).ok === false && auditarLeis(undefined).ok === false && auditarLeis('').ok === false);
130	
131	  // ── auditarLeis: o que NUNCA pode bloquear ──
132	  check('NUNCA BLOQUEIA: as 12 leis certas, corpo livre → ok', auditarLeis(construirSecao()).ok === true);
133	  check('NUNCA BLOQUEIA: as 12 certas com corpo e emendas em blockquote (">") → ok',
134	    auditarLeis(construirSecao(NOMES_CANONICOS, {
135	      corpoExtra: '> Emenda 2026-01-01: ajusta o texto da LEI DO EXEMPLO.\n' +
136	        '> 13. **LEI FALSA DENTRO DE CITAÇÃO** — bloco citado não conta como item.',
137	    })).ok === true);
138	  check('NUNCA BLOQUEIA: espaço duplo entre palavras + acento em forma NFD ainda casa (normaliza) → ok', (() => {
139	    const nomeVariante = 'LEI  DO  NÃO-CHUTE'.normalize('NFD'); // espaço duplo + acento decomposto
140	    return auditarLeis(construirSecao(NOMES_CANONICOS.map((n, idx) => (idx === 1 ? nomeVariante : n)))).ok === true;
141	  })());
142	  check('NUNCA BLOQUEIA: quebras de linha CRLF não derrubam conteúdo correto → ok',
143	    auditarLeis(construirSecao().replace(/\n/g, '\r\n')).ok === true);
144	  check('NUNCA BLOQUEIA: texto antes/depois da seção não interfere → ok',
145	    auditarLeis(`preâmbulo qualquer\n\n${construirSecao()}\n\nrodapé qualquer`).ok === true);
146	
147	  // ── LI-6: 3 mutantes que sobreviviam ao self-test antigo, agora mordidos ──
148	  check(
149	    'LI-6: título "## AS 12 LEIS..." citado NO MEIO de uma frase não inicia seção ' +
150	    '(mata mutante da âncora de RE_SECAO) → secao-ausente', (() => {
151	      const r = auditarLeis('Nota: ver "## AS 12 LEIS DO DESENVOLVIMENTO" citada aqui, no meio da frase.\n\nsem seção real em lugar nenhum.\n');
152	      return r.ok === false && r.problemas[0].startsWith('secao-ausente');
153	    })());
154	  check(
155	    'LI-6: item numerado numa seção POSTERIOR (depois do próximo "## ") não conta pra contagem ' +
156	    '(mata mutante de RE_FIM_SECAO) → contagem', (() => {
157	      const linhas = ['## AS 12 LEIS DO DESENVOLVIMENTO', ''];
158	      NOMES_CANONICOS.slice(0, 11).forEach((nome, idx) => linhas.push(`${idx + 1}. **${nome}** — corpo.`));
159	      linhas.push('', '## Outra seção', `12. **${NOMES_CANONICOS[11]}** — item que NÃO deveria contar, está fora da seção.`);
160	      const r = auditarLeis(linhas.join('\n'));
161	      return r.ok === false && r.problemas.some((p) => p.startsWith('contagem') && p.includes('11'));
162	    })());
163	  check(
164	    'LI-6: blockquote com o NOME EXATO da lei ("> 13. **LEI DO EXTRA**") não conta como item de topo ' +
165	    '(mata mutante de RE_ITEM aceitando blockquote) → ok',
166	    auditarLeis(construirSecao(NOMES_CANONICOS, {
167	      corpoExtra: '> 13. **LEI DO EXTRA** — citação com o padrão exato; não pode contar.',
168	    })).ok === true);
169	  check(
170	    'LI-6: item INDENTADO ("   13. **LEI DO EXTRA**") também não conta como item de topo ' +
171	    '(mata mutante de RE_ITEM aceitando indentação) → ok',
172	    auditarLeis(construirSecao(NOMES_CANONICOS, {
173	      corpoExtra: '   13. **LEI DO EXTRA** — indentado; não pode contar.',
174	    })).ok === true);
175	
176	  // ── LI-1 / LI-7: auditarBussola (despirMarkdown antes de auditar) ──
177	  check('LI-1: comentário HTML esconde SÓ uma lei (A1) → contagem → reprova',
