50	export function julgarSaida({ stdout = '', stderr = '', status = null } = {}) {
51	  const texto = `${stdout}\n${stderr}`;
52	  const m = RE_OK.exec(texto);
53	  if (status !== 0) return { ok: false, motivo: `exit ${status}${/SELF-TEST FALHOU/.test(texto) ? ' (SELF-TEST FALHOU)' : ''}` };
54	  if (!m) return { ok: false, motivo: texto.trim() === '' ? 'saída VAZIA com exit 0 — guard mudo' : 'exit 0 sem a linha "SELF-TEST OK — N/N casos"' };
55	  const n = Number(m[1]), total = Number(m[2]);
