126	function main() {
127	  const casos = [];
128	  const check = (nome, cond) => casos.push({ nome, ok: Boolean(cond) });
129	  casosDoutrina(check);
130	  casosRunner(check);
131	  const falhas = casos.filter((c) => !c.ok);
132	  for (const c of casos) console.log(`  ${c.ok ? '✓' : '✗'} ${c.nome}`);
133	  if (falhas.length) { console.error(`[${NOME}] ❌ doutrina/runner reprovou ${falhas.length} caso(s) — nenhum guard é confiável com a base quebrada.`); process.exitCode = 1; return; }
134	  console.log(`[${NOME}] doutrina+runner OK — ${casos.length}/${casos.length}\n`);
135	
136	  // Contagem FUNCIONAL (issue #17): sem `ruins++` numa linha à parte — apagar essa linha era o
137	  // mutante que mascarava um guard vermelho. `ruins` deriva do array; não há linha de incremento
138	  // para deletar, e o self-test PORTA abaixo roda o runner contra um guard vermelho para provar.
139	  const resultadosGuards = guardsDaPasta().map((g) => ({ g, r: rodarGuard(join(AQUI, g)) }));
140	  // self-tests de COMANDO fora de scripts/guards/ (ex.: reservar-numero.mjs) — mesma doutrina, resolvidos
141	  // SEMPRE contra a pasta-mãe real (PASTA_MAE), nunca contra o AQUI fake do self-test deste runner.
142	  const resultadosFora = SELFTESTS_FORA_DE_GUARDS.map((rel) => ({ g: rel, r: rodarGuard(join(PASTA_MAE, rel)) }));
143	  const resultados = [...resultadosGuards, ...resultadosFora];
144	  for (const { g, r } of resultados) {
