146	    if (!r.ok) ecoarSaidaReprovada(r.stdout, r.stderr);
147	  }
148	  const rodados = resultados.length;
149	  const ruins = resultados.filter((x) => !x.r.ok).length;
150	  const totalEsperado = GUARDS_ESPERADOS.length + SELFTESTS_FORA_DE_GUARDS.length;
151	  if (rodados < totalEsperado) { console.error(`\n[${NOME}] ❌ rodaram ${rodados}; esperados ${totalEsperado} (${GUARDS_ESPERADOS.length} guards + ${SELFTESTS_FORA_DE_GUARDS.length} self-test(s) fora de scripts/guards).`); process.exitCode = 1; return; }
152	  if (ruins) { console.error(`\n[${NOME}] ❌ ${ruins} sem evidência de self-test. Exit 0 sem a linha "SELF-TEST OK — N/N" é guard MUDO, não guard verde.`); process.exitCode = 1; return; }
