167	    check('PORTA BYPASS (R1): runner com pasta de guards vazia → exit 1', st === 1);
168	  } finally { rmSync(vazio, { recursive: true, force: true }); }
169	  // PORTA: um guard VERMELHO entre os esperados → o runner TEM que sair 1 (mata o mutante que apaga
170	  // `if (!r.ok) ruins++` e a inversão do predicado de contagem — o guard mudo do #17, um nível acima).
171	  const comRed = mkdtempSync(join(tmpdir(), 'rst-red-'));
172	  try {
173	    GUARDS_ESPERADOS.forEach((g, i) => writeFileSync(join(comRed, g), i === 0
174	      ? "console.error('[fake] SELF-TEST FALHOU: 1/2'); process.exit(1);\n"
175	      : "console.log('[fake] SELF-TEST OK — 2/2 casos (incl. 1 tentativas de bypass).'); process.exit(0);\n"));
176	    const st = spawnSync(process.execPath, [fileURLToPath(import.meta.url)], { encoding: 'utf8', timeout: 120_000, env: { ...process.env, npm_lifecycle_event: '', RUN_SELFTESTS_DIR: comRed } }).status;
177	    check('PORTA: 1 guard vermelho entre os esperados → runner exit 1 (não mascara guard mudo)', st === 1);
178	  } finally { rmSync(comRed, { recursive: true, force: true }); }
179	  // PORTA (issue #27, causa 3): a saída do guard reprovado aparece IMPRESSA pelo runner, não só o
180	  // resumo "exit 1" — sem isso, reproduzir em container era a única forma de saber por que um guard
181	  // caiu. Sem o conserto de rodarGuard/ecoarSaidaReprovada este caso reprova (vermelho-antes real).
182	  const comEco = mkdtempSync(join(tmpdir(), 'rst-eco-'));
183	  try {
184	    const sinal = 'SINAL-DE-TESTE-CAUSA-3-ISSUE-27';
185	    GUARDS_ESPERADOS.forEach((g, i) => writeFileSync(join(comEco, g), i === 0
186	      ? `console.log('  ✗ caso fake que carrega o sinal'); console.error('[fake] ${sinal} — SELF-TEST FALHOU: 1/2'); process.exit(1);\n`
187	      : "console.log('[fake] SELF-TEST OK — 2/2 casos (incl. 1 tentativas de bypass).'); process.exit(0);\n"));
188	    const r = spawnSync(process.execPath, [fileURLToPath(import.meta.url)], { encoding: 'utf8', timeout: 120_000, env: { ...process.env, npm_lifecycle_event: '', RUN_SELFTESTS_DIR: comEco } });
189	    check(
190	      `PORTA (causa 3, issue #27): saída do guard reprovado aparece impressa pelo runner, não só o resumo — procurando "${sinal}"`,
191	      r.stdout.includes(sinal),
192	    );
193	  } finally { rmSync(comEco, { recursive: true, force: true }); }
194	  // PORTA: self-test FORA de scripts/guards (scripts/reservar-numero.mjs, real) roda de verdade e conta
195	  // pro relatório/total — pasta de guards fake toda verde, RAIZ continua sendo a raiz REAL do repo.
196	  const comOk = mkdtempSync(join(tmpdir(), 'rst-ok-'));
197	  try {
198	    GUARDS_ESPERADOS.forEach((g) => writeFileSync(join(comOk, g), "console.log('[ok] SELF-TEST OK — 1/1 casos (incl. 0 tentativas de bypass).'); process.exit(0);\n"));
199	    const r = spawnSync(process.execPath, [fileURLToPath(import.meta.url)], { encoding: 'utf8', timeout: 600_000, env: { ...process.env, npm_lifecycle_event: '', RUN_SELFTESTS_DIR: comOk } });
200	    check(
201	      'PORTA: self-test fora de scripts/guards (scripts/reservar-numero.mjs) roda e aparece no relatório, contribuindo pro exit',
202	      /reservar-numero\.mjs/.test(r.stdout) && r.status === 0,
203	    );
204	  } finally { rmSync(comOk, { recursive: true, force: true }); }
205	  const dir = mkdtempSync(join(tmpdir(), 'rst-'));
206	  try {
207	    const mudo = join(dir, 'mudo.mjs'); writeFileSync(mudo, 'process.exit(0);\n');
208	    const ok = join(dir, 'ok.mjs'); writeFileSync(ok, "console.log('[ok] SELF-TEST OK — 2/2 casos (incl. 1 tentativas de bypass).');\n");
209	    check('guard falso MUDO (exit 0, sem saída) → reprovado pelo runner', rodarGuard(mudo).ok === false);
210	    check('guard falso com a linha → aprovado pelo runner', rodarGuard(ok).ok === true);
211	  } finally { rmSync(dir, { recursive: true, force: true }); }
212	  process.exitCode = relatarSelfTest(NOME, casos);
213	}
214	
215	// SEM portão de entrypoint, de propósito: este runner vigia a doutrina, então não pode depender dela
216	// para decidir se roda — com `ehEntrypoint` mutado para false (M17), o runner ficaria mudo junto
217	// com os guards e o CI sairia verde (medido em 2026-09-10). Ele é CLI por definição; roda sempre.
218	if (selfTestPedido()) selfTest(); else main();
