67	// Imprime a saída do guard reprovado (issue #27, causa 3) — prioriza linhas com "✗" (os casos que
68	// falharam), cai pras últimas linhas se o padrão não bater. "SELF-TEST OK" é mascarado como
69	// "SELF-TEST OK[eco]" ao ecoar: hoje não vira falso-verde (julgarSaida olha o `status` do PROCESSO
70	// PAI antes do texto — o eco é side-effect de imprimir, nunca entra em julgarSaida), mas é o
71	// instrumento imprimindo, no seu próprio canal, a frase que ELE MESMO usa pra julgar (§5.1.7 do
72	// método: "o instrumento não pode morar dentro do que ele mede") — a máscara fecha essa porta antes
73	// que alguém mude a ordem das checagens de julgarSaida.
74	function ecoarSaidaReprovada(stdout = '', stderr = '') {
75	  const texto = `${stdout}${stderr}`.replace(/SELF-TEST OK/g, 'SELF-TEST OK[eco]');
76	  const linhas = texto.split('\n').map((l) => l.trimEnd()).filter((l) => l !== '');
77	  const comFalha = linhas.filter((l) => l.includes('✗'));
78	  for (const l of (comFalha.length ? comFalha : linhas.slice(-15))) console.log(`      ${l}`);
79	}
